WITH attributed AS (SELECT a.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM promotions a LEFT JOIN promotions pr ON COALESCE(a.channel, 'web') = pr.channel AND a.starts_on BETWEEN pr.starts_on AND pr.ends_on) SELECT CASE WHEN promotion_discount_pct >= 0.3 THEN 'HIGH' ELSE 'LOW' END AS promotion_discount_pct_tier, DATE_TRUNC('QUARTER', starts_on) AS quarter_start, COUNT(CASE WHEN promotion_promo_code = 'SPRING10' THEN 1 END) AS spring10_count, COUNT(CASE WHEN promo_code = 'BUNDLE' THEN 1 END) AS bundle_count, PERCENTILE_APPROX(promo_id, 0.95) AS promo_id_p95 FROM attributed GROUP BY GROUPING SETS ((CASE WHEN promotion_discount_pct >= 0.3 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('QUARTER', starts_on)), (CASE WHEN promotion_discount_pct >= 0.3 THEN 'HIGH' ELSE 'LOW' END), ());
